using Microsoft.EntityFrameworkCore;

namespace DM.EntityFrameworkCore.Tests.Query;

/// <summary>
/// T2 SQL shape tests for the Guid members. Each expression sits in a predicate, so a client side
/// value cannot make the test pass.
/// </summary>
public class DmGuidTranslationTests
{
    /// <summary>
    /// The identifier is generated by the server, which is what makes the two rows of an insert
    /// differ without the client knowing the value.
    /// </summary>
    [Fact]
    public void NewGuid_IsGeneratedByTheServer()
    {
        using var context = new ProbeContext();

        Assert.Equal(
            """
            SELECT "p"."Id", "p"."Key"
            FROM "Probes" AS "p"
            WHERE "p"."Key" <> NEWID()
            """,
            Statement(
                context.Probes
                    .Where(p => p.Key != Guid.NewGuid())
                    .ToQueryString()));
    }

    private static string Statement(string sql)
        => string.Join(
            "\n",
            sql.Replace("\r\n", "\n", StringComparison.Ordinal)
                .Split('\n')
                .Where(line => !line.StartsWith("--", StringComparison.Ordinal))
                .Select(line => line.TrimEnd()));

    private sealed class ProbeContext : DbContext
    {
        public DbSet<Probe> Probes => Set<Probe>();

        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
            => optionsBuilder.UseDm("Server=127.0.0.1:5236;User Id=SYSDBA;PWD=SYSDBA;");
    }

    private sealed class Probe
    {
        public int Id { get; set; }

        public Guid Key { get; set; }
    }
}
